CREATE TYPE public.app_role AS ENUM ('admin','moderator','user');
CREATE TABLE public.profiles (id uuid PRIMARY KEY, nome text NOT NULL DEFAULT '', tipo text NOT NULL DEFAULT 'cuidadora', cidade text NOT NULL DEFAULT '', bio text NOT NULL DEFAULT '', bairros text[] NOT NULL DEFAULT '{}', especialidades text[] NOT NULL DEFAULT '{}', tarifa_hora numeric NOT NULL DEFAULT 0, tarifa_diaria numeric NOT NULL DEFAULT 0, tarifa_plantao12 numeric NOT NULL DEFAULT 0, tarifa_plantao24 numeric NOT NULL DEFAULT 0, verificado boolean NOT NULL DEFAULT false, cpf text UNIQUE, data_nascimento date, email text, telefone text, selfie_url text, status_verificacao text DEFAULT 'pendente', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, role public.app_role NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role); $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY own_profile_insert ON public.profiles FOR INSERT TO authenticated WITH CHECK (id=auth.uid() AND NOT verificado);
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid() OR public.has_role(auth.uid(),'admin')) WITH CHECK (id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_profile_delete ON public.profiles FOR DELETE TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.proteger_perfil_cloud() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('postgres','supabase_admin','service_role') OR auth.role()='service_role' OR public.has_role(auth.uid(),'admin') THEN RETURN NEW; END IF; IF NEW.verificado IS DISTINCT FROM OLD.verificado OR NEW.tipo IS DISTINCT FROM OLD.tipo THEN RAISE EXCEPTION 'Alteração exclusiva do administrador'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER proteger_perfil_cloud BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.proteger_perfil_cloud();
CREATE TABLE public.verificacoes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,cpf text NOT NULL DEFAULT '',data_nascimento text NOT NULL DEFAULT '',documento_path text NOT NULL DEFAULT '',selfie_path text NOT NULL DEFAULT '',nome_documento text NOT NULL DEFAULT '',tipo_documento text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'pendente',score numeric NOT NULL DEFAULT 0,cpf_valido boolean NOT NULL DEFAULT false,face_confere boolean NOT NULL DEFAULT false,antecedentes_status text NOT NULL DEFAULT '',antecedentes_dados jsonb,observacoes text NOT NULL DEFAULT '',revisao_manual boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.verificacoes TO authenticated; GRANT ALL ON public.verificacoes TO service_role; ALTER TABLE public.verificacoes ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_verificacao_read ON public.verificacoes FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY own_verificacao_insert ON public.verificacoes FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status IN ('pendente','em_analise') AND NOT cpf_valido AND NOT face_confere AND score=0);
CREATE TABLE public.documentos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,caminho text NOT NULL,tipo text NOT NULL DEFAULT '',origem text NOT NULL DEFAULT '',mime text NOT NULL DEFAULT '',nome_arquivo text NOT NULL DEFAULT '',tamanho numeric NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.documentos TO authenticated; GRANT ALL ON public.documentos TO service_role; ALTER TABLE public.documentos ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_documentos ON public.documentos FOR ALL TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin')) WITH CHECK(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.contratos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),familia_id uuid NOT NULL,cuidadora_id uuid NOT NULL,criado_por uuid NOT NULL,assistido_nome text NOT NULL DEFAULT '',checkout_url text,cuidadora_aceite_em timestamptz,cuidadora_aceite_nome text NOT NULL DEFAULT '',cuidadora_cidade text NOT NULL DEFAULT '',cuidadora_cpf text NOT NULL DEFAULT '',cuidadora_nome text NOT NULL DEFAULT '',cuidadora_telefone text NOT NULL DEFAULT '',cuidadora_verificada boolean NOT NULL DEFAULT false,data_fim date,data_inicio date NOT NULL,descricao_cuidado text NOT NULL DEFAULT '',emitido_em timestamptz NOT NULL DEFAULT now(),endereco text NOT NULL DEFAULT '',familia_aceite_em timestamptz,familia_aceite_nome text NOT NULL DEFAULT '',familia_bairro text NOT NULL DEFAULT '',familia_cidade text NOT NULL DEFAULT '',familia_cpf text NOT NULL DEFAULT '',familia_nome text NOT NULL DEFAULT '',familia_telefone text NOT NULL DEFAULT '',familia_verificada boolean NOT NULL DEFAULT false,hora_fim text NOT NULL DEFAULT '',hora_inicio text NOT NULL DEFAULT '',motivo_recusa text NOT NULL DEFAULT '',observacoes text NOT NULL DEFAULT '',pagamento_id text,pagamento_status text NOT NULL DEFAULT 'pendente',pago_em timestamptz,recusado_por uuid,regime text NOT NULL DEFAULT '',reserva_id text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'pendente',taxa_percentual numeric NOT NULL DEFAULT 15,termo_texto text NOT NULL DEFAULT '',valor numeric NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.contratos TO authenticated; GRANT ALL ON public.contratos TO service_role; ALTER TABLE public.contratos ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_contratos_read ON public.contratos FOR SELECT TO authenticated USING(auth.uid() IN(familia_id,cuidadora_id) OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.propostas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),familia_id uuid NOT NULL,cuidadora_id uuid NOT NULL,data_servico date NOT NULL,hora_inicio text NOT NULL,hora_fim text NOT NULL,valor_proposto numeric NOT NULL,status text NOT NULL DEFAULT 'pendente',observacao text NOT NULL DEFAULT '',expira_em timestamptz NOT NULL DEFAULT(now()+interval '48 hours'),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.propostas TO authenticated; GRANT ALL ON public.propostas TO service_role; ALTER TABLE public.propostas ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_propostas_read ON public.propostas FOR SELECT TO authenticated USING(auth.uid() IN(familia_id,cuidadora_id) OR public.has_role(auth.uid(),'admin'));
ALTER TABLE public.propostas ADD CONSTRAINT propostas_familia_id_fkey FOREIGN KEY(familia_id) REFERENCES public.profiles(id), ADD CONSTRAINT propostas_cuidadora_id_fkey FOREIGN KEY(cuidadora_id) REFERENCES public.profiles(id);
CREATE TABLE public.conversas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),familia_id uuid NOT NULL,cuidadora_id uuid NOT NULL,assunto text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'pendente',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.conversas TO authenticated; GRANT ALL ON public.conversas TO service_role; ALTER TABLE public.conversas ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_conversas ON public.conversas FOR SELECT TO authenticated USING(auth.uid() IN(familia_id,cuidadora_id) OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.mensagens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversa_id uuid NOT NULL REFERENCES public.conversas(id),remetente_id uuid NOT NULL,mensagem text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.mensagens TO authenticated; GRANT ALL ON public.mensagens TO service_role; ALTER TABLE public.mensagens ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_mensagens ON public.mensagens FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.conversas c WHERE c.id=conversa_id AND auth.uid() IN(c.familia_id,c.cuidadora_id)) OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.mensagens_conversa (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),familia_id uuid NOT NULL,cuidadora_id uuid NOT NULL,remetente_id uuid NOT NULL,mensagem text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.mensagens_conversa TO authenticated; GRANT ALL ON public.mensagens_conversa TO service_role; ALTER TABLE public.mensagens_conversa ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_mensagens_conversa ON public.mensagens_conversa FOR SELECT TO authenticated USING(auth.uid() IN(familia_id,cuidadora_id) OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.alertas_plantao (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),contrato_id uuid NOT NULL REFERENCES public.contratos(id),criado_por uuid NOT NULL,mensagem text NOT NULL,lido_em timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.alertas_plantao TO authenticated; GRANT ALL ON public.alertas_plantao TO service_role; ALTER TABLE public.alertas_plantao ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_alertas ON public.alertas_plantao FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.contratos c WHERE c.id=contrato_id AND auth.uid() IN(c.familia_id,c.cuidadora_id)) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY own_alertas_update ON public.alertas_plantao FOR UPDATE TO authenticated USING(EXISTS(SELECT 1 FROM public.contratos c WHERE c.id=contrato_id AND auth.uid() IN(c.familia_id,c.cuidadora_id))) WITH CHECK(EXISTS(SELECT 1 FROM public.contratos c WHERE c.id=contrato_id AND auth.uid() IN(c.familia_id,c.cuidadora_id)));
CREATE TABLE public.admin_auditoria (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),admin_id uuid NOT NULL,user_id uuid,acao text NOT NULL,caminho text NOT NULL DEFAULT '',detalhe text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_auditoria TO authenticated; GRANT ALL ON public.admin_auditoria TO service_role; ALTER TABLE public.admin_auditoria ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_auditoria_read ON public.admin_auditoria FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
